 "content": "def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Detect the line-pattern object: thick 2 path and surrounding 8 markers.
    # Recolor the separate object matching 8 geometry into the 2-path color.
    # The matching object is the contiguous 8 shape itself, changed to 2.
    for r in range(h):
        for c in range(w):
            if g[r][c]==8:
                g[r][c]=2
    return g
